        """Count and percentage of missing values per column."""
        n = len(self)
        return Table.from_rows(
            {"column": c, "missing": m, "percent": round(100 * m / n, 2) if n else 0.0}
            for c, v in self._cols.items()
            for m in [sum(x is None for x in v)]
