        with open(path, "w", newline="", encoding="utf-8") as f:
            writer = csv.writer(f, delimiter=delimiter)
            writer.writerow(self.columns)
            for values in zip(*self._cols.values()):
                writer.writerow("" if v is None else v for v in values)

