        cols = dict(self._cols)
        cols[name] = list(values)
        return Table(cols)

    def rename(self, mapping: Mapping[str, str] | Callable[[str], str]) -> "Table":
        fn = mapping if callable(mapping) else (lambda n: mapping.get(n, n))
        new = {}
